/bin/zsh -lc "command -v dev-browser && dev-browser --headless --timeout 20 <<'EOF'
const page = await browser.getPage(\"earthquake-app\");
await page.goto(\"file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/earthquake-explorer/2026-07-15-codex-gpt-5-6-sol/index.html\", { waitUntil: \"domcontentloaded\" });
